using System.Data;
using ElevatorSystem.Models;
using Microsoft.Data.SqlClient;

namespace ElevatorSystem.Data;

/// <summary>
/// The only class that talks to the SQL Server database. Every other class goes through it, so
/// no database code is repeated anywhere else.
/// <para>
/// Uses the disconnected model: rows are added to a DataTable inside a DataSet and saved with
/// <see cref="SqlDataAdapter"/>.Update, with the INSERT command generated by
/// <see cref="SqlCommandBuilder"/>. ExecuteNonQuery is only used for the one-off CREATE DATABASE /
/// CREATE TABLE, never for inserts.
/// </para>
/// <para>
/// Each public method catches every failure and throws a <see cref="DataAccessException"/> whose message
/// can be shown to the user. These methods do blocking I/O, so callers run them on a BackgroundWorker.
/// </para>
/// </summary>
public sealed class ElevatorLogRepository
{
    public const string TableName = "ElevatorLog";
    private const string QualifiedTable = "[dbo].[" + TableName + "]";
    private const string SelectColumns = "[Id], [EventTime], [ElevatorId], [Floor], [Status]";
    private const int StatusMaxLength = 255;

    // Short enough that a locked table is reported quickly instead of freezing the log for 30 s.
    private const int CommandTimeoutSeconds = 5;

    // SQL Server error numbers that mean "the database or table is gone": recreate it and try again.
    private static readonly HashSet<int> MissingDatabaseErrors = new() { 4060, 208, 911, 3702, 945 };

    private readonly DatabaseSettings _settings;

    public ElevatorLogRepository()
    {
        _settings = DatabaseSettings.Load();

        var builder = new SqlConnectionStringBuilder
        {
            DataSource = _settings.Server,
            IntegratedSecurity = true,
            // The first connection may have to start LocalDB, which can take a while.
            ConnectTimeout = 30,
            ApplicationName = "ElevatorSystem"
        };

        builder.InitialCatalog = "master";
        MasterConnectionString = builder.ConnectionString;
        builder.InitialCatalog = _settings.Name;
        ConnectionString = builder.ConnectionString;
    }

    public string ConnectionString { get; }
    private string MasterConnectionString { get; }

    /// <summary>Server and database, for status messages, e.g. "(localdb)\MSSQLLocalDB › ElevatorSystem".</summary>
    public string DisplayName => $"{_settings.Server} › {_settings.Name}";

    /// <summary>Problem with appsettings.json, if any (the defaults were used instead).</summary>
    public string? SettingsWarning => _settings.Warning;

    /// <summary>
    /// Makes sure the database and the log table exist, creating them when missing.
    /// Returns true if anything had to be created.
    /// </summary>
    public bool EnsureDatabase()
    {
        try
        {
            return EnsureDatabaseCore();
        }
        catch (Exception ex) when (ex is not DataAccessException)
        {
            throw Translate(ex, "prepare the log database");
        }
    }

    /// <summary>Saves a batch of log entries with DataAdapter.Update (disconnected model).</summary>
    public void InsertLogs(IReadOnlyCollection<LogEntry> entries)
    {
        if (entries.Count == 0)
        {
            return;
        }

        try
        {
            WithRecreateOnMissing(() =>
            {
                using var connection = new SqlConnection(ConnectionString);

                // "WHERE 1 = 0" fetches only the schema; no existing rows are loaded just to append new ones.
                using var adapter = new SqlDataAdapter($"SELECT {SelectColumns} FROM {QualifiedTable} WHERE 1 = 0", connection);
                adapter.SelectCommand.CommandTimeout = CommandTimeoutSeconds;
                using var builder = new SqlCommandBuilder(adapter);

                var dataSet = new DataSet("ElevatorLogs");
                adapter.FillSchema(dataSet, SchemaType.Source, TableName);
                DataTable table = dataSet.Tables[TableName]!;

                foreach (LogEntry entry in entries)
                {
                    DataRow row = table.NewRow();
                    // Id is an IDENTITY column: the command builder leaves it out of the INSERT.
                    row["EventTime"] = entry.EventTime;
                    row["ElevatorId"] = entry.ElevatorId;
                    row["Floor"] = entry.Floor;
                    row["Status"] = entry.Status.Length > StatusMaxLength ? entry.Status[..StatusMaxLength] : entry.Status;
                    table.Rows.Add(row);
                }

                adapter.InsertCommand = builder.GetInsertCommand();
                adapter.InsertCommand.CommandTimeout = CommandTimeoutSeconds;
                adapter.Update(dataSet, TableName);
                return 0;
            });
        }
        catch (Exception ex) when (ex is not DataAccessException)
        {
            throw Translate(ex, "save the operation log");
        }
    }

    /// <summary>Loads the whole log, newest first, into a disconnected DataTable for display.</summary>
    public DataTable LoadLogs()
    {
        try
        {
            return WithRecreateOnMissing(() =>
            {
                using var connection = new SqlConnection(ConnectionString);
                using var adapter = new SqlDataAdapter($"SELECT {SelectColumns} FROM {QualifiedTable} ORDER BY [Id] DESC", connection);
                adapter.SelectCommand.CommandTimeout = CommandTimeoutSeconds;

                var dataSet = new DataSet("ElevatorLogs");
                adapter.Fill(dataSet, TableName);
                return dataSet.Tables[TableName]!;
            });
        }
        catch (Exception ex) when (ex is not DataAccessException)
        {
            throw Translate(ex, "load the operation log");
        }
    }

    private bool EnsureDatabaseCore()
    {
        bool created = false;

        using (var master = new SqlConnection(MasterConnectionString))
        {
            master.Open();
            using var exists = new SqlCommand("SELECT DB_ID(@name)", master);
            exists.Parameters.AddWithValue("@name", _settings.Name);
            if (exists.ExecuteScalar() is DBNull or null)
            {
                // A database name cannot be a parameter; it is validated in DatabaseSettings and bracket-quoted here.
                using var create = new SqlCommand($"CREATE DATABASE [{_settings.Name}]", master);
                create.ExecuteNonQuery();
                created = true;
            }
        }

        using var connection = new SqlConnection(ConnectionString);
        connection.Open();
        using var createTable = new SqlCommand(
            $"""
            IF OBJECT_ID(N'{QualifiedTable}', N'U') IS NULL
            BEGIN
                CREATE TABLE {QualifiedTable}
                (
                    [Id]         INT IDENTITY(1, 1) NOT NULL CONSTRAINT [PK_{TableName}] PRIMARY KEY,
                    [EventTime]  DATETIME2(3)       NOT NULL,
                    [ElevatorId] INT                NOT NULL,
                    [Floor]      INT                NOT NULL,
                    [Status]     NVARCHAR({StatusMaxLength})      NOT NULL
                );
                SELECT 1;
            END
            ELSE
                SELECT 0;
            """, connection);
        created |= (int)createTable.ExecuteScalar()! == 1;

        return created;
    }

    /// <summary>
    /// Runs <paramref name="action"/>. If the database or table was dropped while the program was running,
    /// it is recreated and the action tried once more, so the log is not lost.
    /// </summary>
    private T WithRecreateOnMissing<T>(Func<T> action)
    {
        try
        {
            return action();
        }
        catch (SqlException ex) when (MissingDatabaseErrors.Contains(ex.Number))
        {
            // Pooled connections still point at the dropped database; discard them first.
            SqlConnection.ClearAllPools();
            EnsureDatabaseCore();
            return action();
        }
    }

    /// <summary>Maps low-level exceptions to messages a user can act on.</summary>
    private DataAccessException Translate(Exception ex, string action)
    {
        string reason = ex switch
        {
            SqlException sql => sql.Number switch
            {
                -2 or 1222 => $"The database '{_settings.Name}' did not respond in time. Another program (for example SQL Server Management Studio) may be locking the log table. Close that transaction and try again.",
                // Network errors; LocalDB startup failures arrive as large negative HRESULT-style numbers.
                -1 or 2 or 26 or 40 or 53 or 50 or 52 or < -2 =>
                    $"Could not connect to SQL Server '{_settings.Server}'. Check that SQL Server (LocalDB) is installed and running, or change the server in {DatabaseSettings.FileName}.",
                4060 => $"The database '{_settings.Name}' could not be opened on '{_settings.Server}'.",
                18456 => $"Login to SQL Server '{_settings.Server}' failed for your Windows account.",
                262 or 229 or 230 => $"Your Windows account is not allowed to create or change the database '{_settings.Name}'.",
                1105 or 9002 => $"The database '{_settings.Name}' is full or out of disk space.",
                5120 or 5123 or 5133 or 1802 => $"SQL Server could not create the database files for '{_settings.Name}': {sql.Message}",
                _ => $"SQL Server reported an error ({sql.Number}): {sql.Message}"
            },
            InvalidOperationException => $"The database connection could not be used: {ex.Message}",
            _ => $"Unexpected error: {ex.Message}"
        };

        return new DataAccessException($"Could not {action}. {reason}", ex);
    }
}
